<title>Bot Mitigation at Scale - IEEE S&amp;P Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;600&display=swap');

  :root {
    --bg-primary: #0a1628;
    --bg-secondary: #0f1f3d;
    --bg-card: #132044;
    --bg-card-alt: #0d1a35;
    --accent-blue: #00b4d8;
    --accent-teal: #0ea5e9;
    --accent-cyan: #22d3ee;
    --accent-green: #10b981;
    --accent-amber: #f59e0b;
    --accent-red: #ef4444;
    --text-primary: #f1f5f9;
    --text-secondary: #94a3b8;
    --text-muted: #64748b;
    --border-color: rgba(0, 180, 216, 0.15);
    --border-glow: rgba(0, 180, 216, 0.3);
    --gradient-accent: linear-gradient(135deg, #00b4d8, #0ea5e9, #06b6d4);
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    width: 2480px;
    height: 3508px;
    overflow: hidden;
  }

  .poster {
    width: 2480px;
    height: 3508px;
    padding: 60px 72px;
    display: flex;
    flex-direction: column;
    background:
      radial-gradient(ellipse 80% 50% at 50% 0%, rgba(0, 180, 216, 0.06) 0%, transparent 60%),
      radial-gradient(ellipse 60% 40% at 80% 100%, rgba(14, 165, 233, 0.04) 0%, transparent 50%),
      var(--bg-primary);
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    padding-bottom: 36px;
    border-bottom: 2px solid var(--border-glow);
    margin-bottom: 40px;
    position: relative;
  }

  .header::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%);
    width: 200px;
    height: 2px;
    background: var(--gradient-accent);
  }

  .venue-badge {
    display: inline-block;
    background: linear-gradient(135deg, rgba(0, 180, 216, 0.15), rgba(14, 165, 233, 0.1));
    border: 1px solid rgba(0, 180, 216, 0.3);
    border-radius: 24px;
    padding: 8px 28px;
    font-size: 18px;
    font-weight: 600;
    color: var(--accent-cyan);
    letter-spacing: 1.5px;
    text-transform: uppercase;
    margin-bottom: 20px;
  }

  .title {
    font-size: 52px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.5px;
    background: linear-gradient(to right, #ffffff, #e0f2fe, #bae6fd);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 14px;
  }

  .subtitle {
    font-size: 22px;
    font-weight: 400;
    color: var(--text-secondary);
    line-height: 1.5;
    max-width: 1400px;
    margin: 0 auto;
  }

  /* ===== SECTION STYLES ===== */
  .section {
    margin-bottom: 36px;
  }

  .section-header {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 22px;
  }

  .section-number {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: var(--gradient-accent);
    font-size: 16px;
    font-weight: 700;
    color: #0a1628;
    flex-shrink: 0;
  }

  .section-title {
    font-size: 28px;
    font-weight: 700;
    color: var(--text-primary);
    letter-spacing: -0.3px;
  }

  .section-divider {
    flex: 1;
    height: 1px;
    background: linear-gradient(to right, var(--border-glow), transparent);
  }

  /* ===== THREAT LANDSCAPE ===== */
  .threat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
  }

  .stat-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 32px 28px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .stat-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--gradient-accent);
  }

  .stat-card.highlight {
    border-color: var(--border-glow);
    background: linear-gradient(135deg, rgba(0, 180, 216, 0.08), var(--bg-card));
  }

  .stat-icon {
    width: 48px;
    height: 48px;
    margin: 0 auto 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 12px;
    background: rgba(0, 180, 216, 0.1);
  }

  .stat-value {
    font-size: 56px;
    font-weight: 900;
    color: var(--accent-cyan);
    line-height: 1;
    margin-bottom: 8px;
    font-family: 'JetBrains Mono', monospace;
  }

  .stat-label {
    font-size: 16px;
    font-weight: 500;
    color: var(--text-secondary);
    line-height: 1.4;
  }

  .threat-desc {
    margin-top: 20px;
    padding: 20px 24px;
    background: var(--bg-card-alt);
    border-radius: 12px;
    border-left: 3px solid var(--accent-blue);
    font-size: 18px;
    line-height: 1.6;
    color: var(--text-secondary);
  }

  /* ===== PIPELINE ===== */
  .pipeline-container {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 36px 28px 28px;
    position: relative;
  }

  .pipeline-flow {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 8px;
    position: relative;
  }

  .pipeline-stage {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    position: relative;
    z-index: 1;
  }

  .stage-icon-wrap {
    width: 72px;
    height: 72px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 14px;
    position: relative;
    border: 2px solid var(--border-glow);
    background: var(--bg-secondary);
  }

  .stage-icon-wrap svg {
    width: 32px;
    height: 32px;
  }

  .stage-step {
    position: absolute;
    top: -8px;
    right: -8px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: var(--gradient-accent);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 700;
    color: #0a1628;
  }

  .stage-name {
    font-size: 16px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 6px;
  }

  .stage-action {
    font-size: 13px;
    color: var(--accent-cyan);
    font-weight: 500;
    margin-bottom: 4px;
  }

  .stage-duration {
    font-size: 12px;
    color: var(--text-muted);
    font-family: 'JetBrains Mono', monospace;
    background: rgba(0, 180, 216, 0.08);
    padding: 2px 8px;
    border-radius: 4px;
  }

  .pipeline-arrows {
    position: absolute;
    top: 36px;
    left: 60px;
    right: 60px;
    height: 2px;
    z-index: 0;
  }

  .pipeline-arrows line {
    stroke: var(--accent-blue);
    stroke-width: 2;
    stroke-dasharray: 8 4;
    opacity: 0.5;
  }

  .pipeline-note {
    margin-top: 24px;
    text-align: center;
    padding: 14px 20px;
    background: rgba(0, 180, 216, 0.06);
    border-radius: 10px;
    border: 1px solid rgba(0, 180, 216, 0.12);
  }

  .pipeline-note-text {
    font-size: 16px;
    color: var(--text-secondary);
    font-weight: 400;
  }

  .pipeline-note-text strong {
    color: var(--accent-cyan);
    font-weight: 600;
  }

  /* ===== METRICS HERO ===== */
  .metrics-hero {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 28px;
    margin-bottom: 28px;
  }

  .hero-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 16px;
    padding: 36px 32px;
    display: flex;
    align-items: center;
    gap: 28px;
    position: relative;
    overflow: hidden;
  }

  .hero-card.primary {
    border-color: rgba(16, 185, 129, 0.3);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.06), var(--bg-card));
  }

  .hero-card.secondary {
    border-color: rgba(14, 165, 233, 0.3);
    background: linear-gradient(135deg, rgba(14, 165, 233, 0.06), var(--bg-card));
  }

  .hero-metric {
    flex-shrink: 0;
  }

  .hero-value {
    font-size: 80px;
    font-weight: 900;
    line-height: 1;
    font-family: 'JetBrains Mono', monospace;
  }

  .hero-card.primary .hero-value {
    color: var(--accent-green);
  }

  .hero-card.secondary .hero-value {
    color: var(--accent-cyan);
  }

  .hero-unit {
    font-size: 36px;
    font-weight: 600;
  }

  .hero-desc {
    font-size: 18px;
    color: var(--text-secondary);
    line-height: 1.5;
    font-weight: 400;
  }

  .hero-label {
    font-size: 16px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 4px;
  }

  /* ===== SUPPORTING METRICS ===== */
  .metrics-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
  }

  .mini-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 22px 24px;
    display: flex;
    align-items: center;
    gap: 18px;
  }

  .mini-value {
    font-size: 32px;
    font-weight: 800;
    color: var(--accent-amber);
    font-family: 'JetBrains Mono', monospace;
    flex-shrink: 0;
  }

  .mini-label {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.4;
  }

  /* ===== COMPARISON TABLE ===== */
  .comparison-table {
    width: 100%;
    border-collapse: collapse;
    background: var(--bg-card);
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--border-color);
  }

  .comparison-table thead th {
    padding: 14px 20px;
    text-align: left;
    font-size: 14px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    border-bottom: 1px solid var(--border-color);
    background: rgba(0, 0, 0, 0.2);
  }

  .comparison-table thead th:nth-child(2) {
    color: var(--accent-red);
    opacity: 0.8;
  }

  .comparison-table thead th:nth-child(3) {
    color: var(--accent-green);
  }

  .comparison-table tbody td {
    padding: 14px 20px;
    font-size: 16px;
    border-bottom: 1px solid rgba(0, 180, 216, 0.06);
  }

  .comparison-table tbody td:first-child {
    font-weight: 500;
    color: var(--text-secondary);
  }

  .comparison-table tbody td:nth-child(2) {
    font-family: 'JetBrains Mono', monospace;
    color: #f87171;
    font-weight: 500;
  }

  .comparison-table tbody td:nth-child(3) {
    font-family: 'JetBrains Mono', monospace;
    color: #34d399;
    font-weight: 600;
  }

  .comparison-table tbody tr:last-child td {
    border-bottom: none;
  }

  .improvement-badge {
    display: inline-block;
    background: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 4px;
    margin-left: 8px;
  }

  /* ===== TRADE-OFFS ===== */
  .tradeoff-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .tradeoff-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 24px;
    display: flex;
    gap: 16px;
  }

  .tradeoff-icon {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    background: rgba(0, 180, 216, 0.08);
    border: 1px solid rgba(0, 180, 216, 0.15);
  }

  .tradeoff-icon svg {
    width: 22px;
    height: 22px;
  }

  .tradeoff-title {
    font-size: 17px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 6px;
  }

  .tradeoff-text {
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.5;
  }

  /* ===== KEY TAKEAWAYS ===== */
  .takeaways {
    background: linear-gradient(135deg, rgba(0, 180, 216, 0.06), rgba(14, 165, 233, 0.04));
    border: 1px solid var(--border-glow);
    border-radius: 16px;
    padding: 28px 32px;
  }

  .takeaway-list {
    list-style: none;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }

  .takeaway-item {
    display: flex;
    gap: 14px;
    align-items: flex-start;
  }

  .takeaway-num {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    background: var(--gradient-accent);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    font-weight: 700;
    color: #0a1628;
    flex-shrink: 0;
    margin-top: 2px;
  }

  .takeaway-text {
    font-size: 16px;
    color: var(--text-secondary);
    line-height: 1.5;
  }

  /* ===== FOOTER ===== */
  .footer {
    margin-top: auto;
    padding-top: 20px;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 14px;
    color: var(--text-muted);
  }

  .footer-left {
    display: flex;
    align-items: center;
    gap: 20px;
  }

  .footer-sep {
    width: 1px;
    height: 16px;
    background: var(--text-muted);
    opacity: 0.3;
  }

  /* ===== DECORATIVE ===== */
  .glow-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-cyan);
    box-shadow: 0 0 8px var(--accent-cyan);
    margin-right: 8px;
  }

  .arrow-right {
    color: var(--accent-blue);
    font-size: 20px;
    opacity: 0.6;
  }

  /* Pipeline SVG arrow connectors */
  .pipeline-connector {
    position: absolute;
    top: 36px;
    left: 0;
    right: 0;
    height: 4px;
    z-index: 0;
    pointer-events: none;
  }

  /* Hover glow on hero cards */
  .hero-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
  }
  .hero-card.primary::before {
    background: linear-gradient(to right, var(--accent-green), transparent);
  }
  .hero-card.secondary::before {
    background: linear-gradient(to right, var(--accent-cyan), transparent);
  }
</style>
</head>
