import { chromium } from 'playwright';
import { fileURLToPath } from 'url';
import path from 'path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

(async () => {
  const browser = await chromium.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-gpu']
  });

  const page = await browser.newPage();

  // Set viewport to A1 portrait dimensions (scaled for rendering)
  await page.setViewportSize({ width: 2480, height: 3508 });

  // Load the HTML file
  const htmlPath = path.join(__dirname, 'poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle', timeout: 30000 });

  // Wait for fonts to load
  await page.waitForTimeout(3000);

  // Take screenshot at full resolution
  const outputPath = path.join(__dirname, 'final_poster.png');
  await page.screenshot({
    path: outputPath,
    fullPage: false,
    type: 'png',
  });

  console.log(`Poster saved to: ${outputPath}`);

  await browser.close();
})();

